/**
 * A module const named like an object key, a member name or a callback
 * parameter inside another module const is no read of it. The client module
 * must not declare it: it reads `process`, so declaring it throws in the
 * browser before the click listener is attached. A module const the other one
 * does read (`base`) stays declared. The dependencies of a module const come
 * from the free identifiers of its initializer's AST, not from a token scan of
 * its value text.
 *
 * Snapshots in `__snapshots__/module-const-member-key-hydrate.{html,client.js}`
 * are regenerated by
 * `bun run packages/adapter-tests/scripts/snapshot.ts module-const-member-key-hydrate`.
 */

import { defineSharedFixture, type SharedFixtureSpec } from './_helpers'

const label = 'p[data-slot="label"]'
const tag = 'p[data-slot="tag"]'
const button = 'button'

export const spec: SharedFixtureSpec = {
  id: 'module-const-member-key-hydrate',
  componentName: 'ModuleConstMemberKeyHydrate',
  sourceRoot: 'fixture',
  description: 'A module const named only like an object key, member name or callback parameter in another module const is not declared in the client module, so the component hydrates',
  interactions: [
    { type: 'expectText', selector: label, text: 'm' },
    { type: 'expectText', selector: tag, text: 's' },
    { type: 'expectText', selector: button, text: '0' },
    { type: 'click', selector: button },
    { type: 'expectText', selector: button, text: '1' },
  ],
}

export const fixture = defineSharedFixture(spec)
